import { errorText, helpText } from './argparse_format.mjs';

function isNegativeNumberLike(token) {
  return /^-\d+$/.test(token) || /^-\d*\.\d+$/.test(token);
}

function blocksOptionValue(token) {
  return token === '--' || (token.startsWith('-') && token !== '-' && !isNegativeNumberLike(token));
}

export function parseTest3Args(argv, programName) {
  let aValue;
  const extras = [];
  let endOfOptions = false;

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (endOfOptions) {
      extras.push(token);
      continue;
    }

    if (token === '-h' || token === '--help') {
      return {
        kind: 'help',
        exitCode: 0,
        text: helpText(programName),
      };
    }

    if (token === '--') {
      endOfOptions = true;
      continue;
    }

    if (token === '--a') {
      const next = argv[index + 1];

      if (next === undefined || blocksOptionValue(next)) {
        return {
          kind: 'error',
          exitCode: 2,
          text: errorText(programName, 'argument --a: expected one argument'),
        };
      }

      aValue = next;
      index += 1;
      continue;
    }

    if (token.startsWith('--a=')) {
      aValue = token.slice(4);
      continue;
    }

    extras.push(token);
  }

  if (aValue === undefined) {
    return {
      kind: 'error',
      exitCode: 2,
      text: errorText(programName, 'the following arguments are required: --a'),
    };
  }

  if (extras.length > 0) {
    return {
      kind: 'error',
      exitCode: 2,
      text: errorText(programName, `unrecognized arguments: ${extras.join(' ')}`),
    };
  }

  return {
    kind: 'ok',
    exitCode: 0,
    values: {
      a: aValue,
    },
  };
}

