import { programNameFromProcess } from './lib/cli/path_utils.mjs';
import { parseTest3Args } from './lib/cli/test3_args.mjs';
import { StemmingAnalyzer } from './lib/whoosh/analysis.mjs';
import { Schema, TEXT } from './lib/whoosh/fields.mjs';

export function main(argv = process.argv.slice(2)) {
  const programName = programNameFromProcess(process.argv);
  const parseResult = parseTest3Args(argv, programName);

  if (parseResult.kind === 'help') {
    process.stdout.write(parseResult.text);
    return parseResult.exitCode;
  }

  if (parseResult.kind === 'error') {
    process.stderr.write(parseResult.text);
    return parseResult.exitCode;
  }

  const analyzer = new StemmingAnalyzer();
  const schema = new Schema({ content: TEXT({ analyzer }) });

  console.log(String(schema));
  return 0;
}

const exitCode = main();

if (exitCode !== 0) {
  process.exit(exitCode);
}
